  const linked=await page.$eval('.nw-motion-dialog iframe',f=>{const d=f.contentDocument,fr=f.getBoundingClientRect(),nodes=Array.from(d.querySelectorAll('[data-nw-stream-slot]')),host=nodes[0].offsetParent,r=host.getBoundingClientRect(),clip=nodes[0].__nwMotionClip,tiles=nodes.flatMap(n=>n.__nwMotionInstances.map(t=>({...t,id:n.dataset.id}))).sort((a,b)=>b.depth-a.depth),inside=(p,x,y)=>{let yes=false;for(let i=0,j=p.length-1;i<p.length;j=i++)if((p[i].y>y)!==(p[j].y>y)&&x<(p[j].x-p[i].x)*(y-p[i].y)/(p[j].y-p[i].y)+p[i].x)yes=!yes;return yes;},points=new Map();for(let y=clip.top+12;y<clip.top+clip.height-12;y+=8)for(let x=clip.left+12;x<clip.left+clip.width-12;x+=8){const t=tiles.find(t=>inside(t.polygon,x,y));if(!t)continue;const list=points.get(t.id)||[];if(list.some(p=>p.depth===t.depth))continue;list.push({depth:t.depth,x:fr.left+(r.left+x)*fr.width/f.clientWidth,y:fr.top+(r.top+y)*fr.height/f.clientHeight});points.set(t.id,list);if(list.length===2)return{id:t.id,points:list};}return null;});assert.ok(linked,'Repeated sources have separately selectable visible copies');for(const p of linked.points){await page.mouse.click(p.x,p.y);assert.equal(await page.$eval('[data-motion-layer="'+linked.id+'"]',n=>n.getAttribute('aria-pressed')),'true');assert.equal(await page.$eval('.nw-motion-dialog iframe',(f,id)=>f.contentDocument.querySelector('[data-id="'+id+'"]').__nwTickerSelection.classList.contains('nw-motion-selected'),linked.id),true);}
  await change('[data-motion-stream-count]','10');for(const [key,value] of [['size','42'],['spacing','20'],['focusGap','130'],['cornerRadius','3']])await change('[data-motion-stream="'+key+'"]',value);await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="turns"]','3');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="scrollLength"]','420');assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.deepEqual(geometry(await pose(.1)),geometry(await pose(.9)));assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi secuencia');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,'iso-focus-sequence');assert.equal(saved.config.stream.focusGap,130);assert.equal(saved.assets.length,10);await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));assert.deepEqual(copied.map(n=>n.src),start.map(n=>n.src));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,project:JSON.stringify(project),group:g,outside:sec().elements[0],length:sec().sdLength,enabled:sec().sdEnabled};});assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);assert.equal(inserted.group.bg,'transparent');assert.deepEqual(inserted.outside,before.outside);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-focus-card'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#focus-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#focus-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#focus-export',inserted.gid);await page.evaluate(()=>document.querySelector('#focus-export').remove());
  await page.evaluate(id=>{NAGWEB_SCROLL_DIRECTOR.scrub(id,.25);NAGWEB_MOTION_LAB.edit(id);},inserted.gid);await ready();await change('[data-motion-stream="focusGap"]','145');await page.$eval('#preview',f=>f.contentDocument.body.dataset.focusSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.focusSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&f.contentDocument.querySelector('.nw-focus-card');},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scroll=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="focusGap"]',n=>n.value),'145');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().sdEnabled),false);await exported(inserted.gid);const clock=await page.$eval('#focus-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#focus-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});assert.equal(await page.$eval('#focus-export',f=>!!f.contentDocument.querySelector('.nw-sd-active')),false);await page.evaluate(()=>document.querySelector('#focus-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scroll);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);assert.equal(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwMotionInstance.stream.kind,inserted.gid),'iso-focus-sequence');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="iso-focus-sequence"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/iso-focus-sequence-mobile.png'});await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.1),await pose(.9));await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="iso-focus-sequence"]');await ready();await page.click('[data-motion-insert]');const newScene=await page.evaluate(()=>({gid:sec().nwMotionSceneGroup,config:sec().elements.find(e=>e.nwMotionInstance).nwMotionInstance}));assert.equal(newScene.config.template,'iso-focus-sequence');assert.ok(newScene.gid);await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),newScene.gid);await ready();await page.click('[data-motion-close]');
